#!/bin/sh
# Pin the clock: the RTC now follows the host by default, and Pokemon
# tints the overworld by time of day, so replays need a fixed time to stay
# byte-identical.
export NDS_RTC="2026-08-02 12:30:00"
# Replays Pokémon Platinum from boot to the bedroom overworld (~26400 frames).
# Derived 2026-08-09. Gotchas: second touch gate resets on A presses (touch-only),
# Poké Ball center button at (127,92), name typed via A presses then Start->OK.
cd "$(dirname "$0")/.." || exit 1
# Replays keep their own save file so a real playthrough's save is safe.
: "${NDS_SAV:=${TMPDIR:-/tmp}/nds-replay-overworld.sav}"
export NDS_SAV
NDS_FRAMES=${NDS_FRAMES:-26400} \
NDS_INPUT="400-410:a,600-610:start,900-910:a,1200-1210:a,1500-1510:a,1800-1810:a,2100-2110:a,2400-2410:a,2700-2710:a,3000-3010:a,3300-3310:a,3600-3610:a,3900-3910:a,4200-4210:a,4500-4510:a,4800-4810:a,5100-5110:a,5400-5410:a,5700-5710:a,5900-5910:a,6200-6210:a,6500-6510:a,6800-6810:a,7100-7110:a,7400-7410:a,7700-7710:a,8000-8010:a,9300-9310:a,9500-9510:down,9650-9660:down,9800-9810:a,10100-10110:a,10400-10410:a,12600-12610:a,12900-12910:a,13200-13210:a,13500-13510:a,13800-13810:a,14100-14110:a,14400-14410:a,14700-14710:a,15000-15010:a,15300-15310:a,15600-15610:a,15900-15910:a,16200-16210:a,16500-16510:a,16800-16810:a,17100-17110:a,18100-18110:start,18400-18410:a,18700-18710:a,19000-19010:a,19300-19310:a,19600-19610:a,19900-19910:a,20200-20210:a,20500-20510:down,20700-20710:a,21000-21010:a,21300-21310:a,21600-21610:a,21900-21910:a,22200-22210:a,22500-22510:a,22800-22810:a,23100-23110:a,23400-23410:a,23700-23710:a,24000-24010:a,24300-24310:a,24600-24610:a,24900-24910:a,25200-25210:a,25500-25510:a,25800-25810:a,26100-26110:a" \
NDS_TOUCH="6000-6060:119,80;6300-6360:119,80;6600-6660:119,80;8150-8210:119,79;8450-8510:119,79;8750-8810:119,79;9050-9110:119,79;10700-10760:127,92;11000-11060:127,92;11300-11360:127,92;11600-11660:127,92;11900-11960:127,92;12200-12260:127,92;17450-17470:28,98;17600-17620:233,73" \
